targets.expr:
(
  sum by (model) (
    rate(llamacpp:prompt_tokens_total{job="llama-cpp",service!~".*test.*"}[2m])
  )
  /
  clamp_min(
    sum by (model) (
      rate(llamacpp:prompt_seconds_total{job="llama-cpp",service!~".*test.*"}[2m])
    ),
    0.001
  )
)
and on (model)
(
  max by (model) (up{job="llama-cpp",service!~".*test.*"} == 1)
)

(
  sum by (model) (
    rate(llamacpp:tokens_predicted_total{job="llama-cpp",service!~".*test.*"}[2m])
  )
  /
  clamp_min(
    sum by (model) (
      rate(llamacpp:tokens_predicted_seconds_total{job="llama-cpp",service!~".*test.*"}[2m])
    ),
    0.001
  )
)
and on (model)
(
  max by (model) (up{job="llama-cpp",service!~".*test.*"} == 1)
)
